using System.ComponentModel.DataAnnotations;
using System.Security.Claims;
using EduSphere.Domain.Entities;
using EduSphere.Domain.Enums;
using EduSphere.Infrastructure;
using EduSphere.Web.Authorization;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Mvc.RazorPages;
using Microsoft.EntityFrameworkCore;

namespace EduSphere.Web.Pages.Enterprise;
[Authorize(Policy=AuthorizationPolicies.CommunicationManager)]
public sealed class CommunicationDepthModel(TenantDbContext db):PageModel
{
 public IReadOnlyList<Branch> Branches{get;private set;}=[];public IReadOnlyList<NotificationTemplate> Templates{get;private set;}=[];public IReadOnlyList<StudentProfile> Students{get;private set;}=[];public IReadOnlyList<TeacherProfile> Teachers{get;private set;}=[];public IReadOnlyList<ApplicationUser> Parents{get;private set;}=[];public IReadOnlyList<CommunicationCampaign> Campaigns{get;private set;}=[];public IReadOnlyList<ParentTeacherMeeting> Meetings{get;private set;}=[];public IReadOnlyList<Circular> Circulars{get;private set;}=[];public IReadOnlyList<NotificationDeadLetter> DeadLetters{get;private set;}=[];
 [BindProperty]public CampaignInput Campaign{get;set;}=new();[BindProperty]public MeetingInput Meeting{get;set;}=new();[BindProperty]public CircularInput Circular{get;set;}=new();[BindProperty]public LocalizationInput Localization{get;set;}=new();
 public sealed class CampaignInput{public Guid? BranchId{get;set;}[Required,StringLength(180)]public string Name{get;set;}="";public AnnouncementAudience Audience{get;set;}public CommunicationChannel Channel{get;set;}public Guid? TemplateId{get;set;}[StringLength(250)]public string? Subject{get;set;}[Required,StringLength(4000)]public string Body{get;set;}="";public DateTime ScheduledOn{get;set;}=DateTime.Now.AddHours(1);}
 public sealed class MeetingInput{[Required]public Guid? BranchId{get;set;}[Required]public Guid? StudentProfileId{get;set;}[Required]public Guid? TeacherProfileId{get;set;}[Required]public Guid? ParentUserId{get;set;}public DateTime StartsOn{get;set;}=DateTime.Now.AddDays(1);public int DurationMinutes{get;set;}=30;[StringLength(500)]public string? Agenda{get;set;}[StringLength(500)]public string? MeetingUrl{get;set;}}
 public sealed class CircularInput{public Guid? BranchId{get;set;}[Required,StringLength(180)]public string Title{get;set;}="";[Required,StringLength(8000)]public string ContentHtml{get;set;}="";[StringLength(500)]public string? Summary{get;set;}public AnnouncementAudience Audience{get;set;}public DateTime? PublishOn{get;set;}=DateTime.Now;}
 public sealed class LocalizationInput{[Required]public Guid? TemplateId{get;set;}[Required,StringLength(10)]public string Locale{get;set;}="en-IN";[StringLength(250)]public string? Subject{get;set;}[Required,StringLength(4000)]public string Body{get;set;}="";}
 public async Task OnGetAsync()=>await Load();
 public async Task<IActionResult> OnPostCampaignAsync(){if(!ModelState.IsValid){await Load();return Page();}db.CommunicationCampaigns.Add(new(){BranchId=Campaign.BranchId,Name=Campaign.Name.Trim(),Audience=Campaign.Audience,Channel=Campaign.Channel,NotificationTemplateId=Campaign.TemplateId,Subject=Campaign.Subject,Body=Campaign.Body,ScheduledOn=Campaign.ScheduledOn.ToUniversalTime(),Status=CampaignStatus.Scheduled});await db.SaveChangesAsync();return RedirectToPage();}
 public async Task<IActionResult> OnPostMeetingAsync(){var end=Meeting.StartsOn.AddMinutes(Math.Clamp(Meeting.DurationMinutes,10,180));if(await db.ParentTeacherMeetings.AnyAsync(x=>x.TeacherProfileId==Meeting.TeacherProfileId&&x.Status!=ParentTeacherMeetingStatus.Cancelled&&x.StartsOn<end&&x.EndsOn>Meeting.StartsOn))ModelState.AddModelError("Meeting.StartsOn","The teacher already has a meeting in this time slot.");if(!ModelState.IsValid){await Load();return Page();}db.ParentTeacherMeetings.Add(new(){BranchId=Meeting.BranchId!.Value,StudentProfileId=Meeting.StudentProfileId!.Value,TeacherProfileId=Meeting.TeacherProfileId!.Value,ParentUserId=Meeting.ParentUserId!.Value,StartsOn=Meeting.StartsOn,EndsOn=end,Agenda=Meeting.Agenda,MeetingUrl=Meeting.MeetingUrl,Status=ParentTeacherMeetingStatus.Confirmed});await db.SaveChangesAsync();return RedirectToPage();}
 public async Task<IActionResult> OnPostCircularAsync(){if(!ModelState.IsValid){await Load();return Page();}db.Circulars.Add(new(){BranchId=Circular.BranchId,Title=Circular.Title.Trim(),ContentHtml=Circular.ContentHtml,Summary=Circular.Summary,Audience=Circular.Audience,PublishOn=Circular.PublishOn,Status=CircularStatus.Review});await db.SaveChangesAsync();return RedirectToPage();}
 public async Task<IActionResult> OnPostCircularStatusAsync(Guid id,CircularStatus status){var x=await db.Circulars.FindAsync(id);if(x is null)return NotFound();x.Status=status;if(status==CircularStatus.Approved){x.ApprovedByUserId=UserId();x.ApprovedOn=DateTime.UtcNow;}if(status==CircularStatus.Published)x.PublishOn??=DateTime.UtcNow;await db.SaveChangesAsync();return RedirectToPage();}
 public async Task<IActionResult> OnPostLocalizationAsync(){if(!ModelState.IsValid){await Load();return Page();}var template=await db.NotificationTemplates.FindAsync(Localization.TemplateId);if(template is null)return NotFound();var existing=await db.NotificationTemplateLocalizations.FirstOrDefaultAsync(x=>x.NotificationTemplateId==template.Id&&x.Locale==Localization.Locale);if(existing is null)db.NotificationTemplateLocalizations.Add(new(){NotificationTemplateId=template.Id,Locale=Localization.Locale,SubjectTemplate=Localization.Subject,BodyTemplate=Localization.Body});else{existing.SubjectTemplate=Localization.Subject;existing.BodyTemplate=Localization.Body;}var version=await db.NotificationTemplateVersions.Where(x=>x.NotificationTemplateId==template.Id).MaxAsync(x=>(int?)x.Version)??0;db.NotificationTemplateVersions.Add(new(){NotificationTemplateId=template.Id,Version=version+1,SubjectTemplate=Localization.Subject,BodyTemplate=Localization.Body,PublishedByUserId=UserId()});await db.SaveChangesAsync();return RedirectToPage();}
 public async Task<IActionResult> OnPostRequeueAsync(Guid id){var dead=await db.NotificationDeadLetters.FindAsync(id);if(dead is null)return NotFound();var recipient=dead.NotificationRecipientId.HasValue?await db.NotificationRecipients.FindAsync(dead.NotificationRecipientId):null;if(recipient is not null){recipient.Status=NotificationStatus.Queued;recipient.ErrorMessage=null;}dead.Status=DeadLetterStatus.Requeued;dead.ResolvedOn=DateTime.UtcNow;await db.SaveChangesAsync();return RedirectToPage();}
 private async Task Load(){Branches=await db.Branches.OrderBy(x=>x.Name).ToListAsync();Templates=await db.NotificationTemplates.OrderBy(x=>x.Name).ToListAsync();Students=await db.StudentProfiles.OrderBy(x=>x.FirstName).ToListAsync();Teachers=await db.TeacherProfiles.OrderBy(x=>x.FirstName).ToListAsync();Parents=await db.Users.Where(x=>x.UserType==UserType.Parent).OrderBy(x=>x.FirstName).ToListAsync();Campaigns=await db.CommunicationCampaigns.OrderByDescending(x=>x.ScheduledOn).Take(50).ToListAsync();Meetings=await db.ParentTeacherMeetings.Include(x=>x.StudentProfile).Include(x=>x.TeacherProfile).OrderByDescending(x=>x.StartsOn).Take(50).ToListAsync();Circulars=await db.Circulars.OrderByDescending(x=>x.CreatedOn).Take(50).ToListAsync();DeadLetters=await db.NotificationDeadLetters.OrderByDescending(x=>x.DeadLetteredOn).Take(50).ToListAsync();}
 private Guid UserId()=>Guid.Parse(User.FindFirstValue(ClaimTypes.NameIdentifier)!);
}
